__mods["main"] = function()
-- HyleSolo - a CES extension that hosts a SINGLE-NODE (transportless) hyle-services
-- blockchain inside cesluajitd. Enabling the extension does NOT run a chain; it just
-- loads and lets you set the config. Two admin buttons drive it:
--   Start  - boot a node from the current config and heartbeat blocks.
--   Stop   - tear the node down.
-- Disabling / uninstalling the extension kills this cesluajitd process, which
-- destroys the in-process node too, so that also stops the chain.
--
-- Default config is a 1-node chain: this program's own key is the sole validator
-- and proposer (its own 1-of-1 quorum), so it commits a block every block_pace_ms
-- with no peers. The extension config IS the hyle genesis/economy config.
--
-- Runs over the ces.hyle.solo binding (extension-only / privileged /s/), which needs
-- a cesluajitd built with --hyle. The `hyle` name/namespace is reserved for the future
-- transport-enabled multi-node chain; HyleSolo runs side-by-side with it.

local cfg = {}
local running = false
local heartbeat_armed = false

-- Pubkeys arrive as raw 32-byte strings; hex them for display.
local function hex(s)
  return (s:gsub(".", function(c) return string.format("%02x", c:byte()) end))
end

-- Read a scalar meter binding, tolerating an older node that lacks it (-> "?").
local function meter(fn)
  return fn and tostring(fn()) or "?"
end

local function has_binding()
  return ces.hyle ~= nil and ces.hyle.solo ~= nil and ces.hyle.solo.start ~= nil
end

local function do_start()
  if running then return "already running (height " .. tostring(ces.hyle.solo.height()) .. ")" end
  if not has_binding() then return "ces.hyle.solo absent -- build the node with --hyle" end
  local pace = tonumber(cfg.block_pace_ms) or 1000
  ces.hyle.solo.start{
    chain_id     = cfg.chain_id or "hylesolo",
    alloc        = tonumber(cfg.alloc) or 1000000000,   -- genesis funds the program's own account
    fee_transfer = tonumber(cfg.fee_transfer) or 1,
    fee_entry    = tonumber(cfg.fee_entry) or 1,
    fee_mint     = tonumber(cfg.fee_mint) or 1,
    reward_base  = tonumber(cfg.reward_base) or 2,
  }
  running = true
  -- Arm the heartbeat exactly once; the tick is a no-op while stopped. Solo is its
  -- own quorum, so a tick proposes+precommits+commits synchronously and returns --
  -- it never blocks the cooperative VM.
  if not heartbeat_armed then
    ces.every(pace, function() if running then ces.hyle.solo.tick() end end)
    heartbeat_armed = true
  end
  ces.log("hylesolo: started chain '" .. (cfg.chain_id or "hylesolo") .. "', one block every " .. pace .. "ms")
  return "started chain '" .. (cfg.chain_id or "hylesolo") .. "'"
end

local function do_stop()
  if not running then return "not running" end
  running = false
  if ces.hyle and ces.hyle.solo and ces.hyle.solo.stop then ces.hyle.solo.stop() end
  ces.log("hylesolo: stopped")
  return "stopped"
end

ces.extension_admin{
  status = function()
