    return {
      state      = "running",
      chain      = ces.hyle.solo.chain_id(),
      height     = tostring(ces.hyle.solo.height()),
      balance    = meter(ces.hyle.solo.balance),   -- the validator's own minted balance
      accounts   = meter(ces.hyle.solo.accounts),  -- RAM-state cell counts (a / e)
      entries    = meter(ces.hyle.solo.entries),
      txs        = meter(ces.hyle.solo.txs),        -- lifetime meters, reset on Start
      queries    = meter(ces.hyle.solo.queries),
