    return "unknown command: " .. tostring(id)
  end,

  config_defaults = table.concat({
    "# HyleSolo single-node blockchain -- this program's own key is the sole validator.",
    "chain_id = hylesolo",
    "block_pace_ms = 1000",
    "# genesis allocation to the program's own account (whole credits)",
    "alloc = 1000000000",
    "# economy fees + floor-difficulty mint reward (whole credits)",
    "fee_transfer = 1",
    "fee_entry = 1",
    "fee_mint = 1",
    "reward_base = 2",
    "",
  }, "\n"),
  on_config = function(c) cfg = c end,   -- store only; the chain runs on Start, not on enable
}

ces.run()

end

CES_MANIFEST = { name = "HyleSolo", version = "0.1", description = "Boots a SINGLE-NODE (transportless) hyle-services blockchain inside cesluajitd, over the ces.hyle.solo binding. The extension's own program key is the sole validator, producing one block every block_pace_ms. The extension config IS the hyle genesis/economy config. Requires a cesluajitd built with --hyle. Reserves the `hyle` name for the future multi-node chain; runs side-by-side with it." }
